+                value: null,
+                reason: 'task-finished',
+                envelope: this.currentEnvelope
+            };
+        }
+        const accepted = this.isCurrent()
+            && (completedRevision === undefined || completedRevision === this.owner.context.sourceRevision);
+        this.finished = true;
+        this.currentEnvelope = this.owner.finishTask(
